class Router:
    def __init__(self):
        self._routes = {}

    def register(self, method, path, command_cls):
        self._routes[(method, path)] = command_cls

    def handle(self, req):
        command_cls = self._routes.get((req.method, req.path))
        if command_cls is None:
            return 404
        command = command_cls(req) if command_cls._takes_request else command_cls()
        return command.execute()


